with tempfile.TemporaryDirectory(prefix='afterglow-description-ui-') as output:
    sources=[]
    for name,body in stubs.items():
        path=Path(output)/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_text(body);sources.append(path)
    base=root/'extensions/extension/src/main/java/app/afterglow/extension'
    production=list((base/'menus').glob('DescriptionHeader*.java'))
    if os.environ.get('DESCRIPTION_ACTIONS_SOURCE'):
        production=[p for p in production if p.name!='DescriptionHeaderActions.java']+[Path(os.environ['DESCRIPTION_ACTIONS_SOURCE'])]
    sources += production+[base/'menus'/name for name in ['LongPressCaptureContext.java','LongPressCapturePolicy.java','LongPressTextPolicy.java','LongPressMountedText.java','LongPressMountedTextModel.java']]+[base/'settings/ThemeJson.java',root/'tools/jvm/DescriptionHeaderBindingTest.java',root/'tools/jvm/DescriptionHeaderContentTest.java']
    subprocess.run(['javac','-encoding','UTF-8','-d',output,*map(str,sources)],check=True)
    subprocess.run(['java','-cp',output,'DescriptionHeaderBindingTest'],check=True,timeout=20)
    subprocess.run(['java','-cp',output,'DescriptionHeaderContentTest'],check=True,timeout=20)
